var app=angular.module('eventApp',[]); app.controller('EventCtrl',function($scope,$http){$scope.showBox=true;$scope.disableButton=false;$scope.students=[];$scope.loadStudents=function(){$http.get('http://localhost:3000/api/students').then(function(r){$scope.students=r.data;$scope.mysqlStatus='Data loaded from MySQL through the backend API.';},function(){$scope.mysqlStatus='Backend not running. Start angularjs/04-events/backend with npm install and npm start.';});};$scope.clicked=function(e){$scope.clickText='ng-click received event type: '+e.type+' at x='+e.clientX+', y='+e.clientY;};$scope.moved=function(e){$scope.mouseText='Mouse position: '+e.clientX+', '+e.clientY;};});
